#!/usr/bin/env python3
"""LITCO GAME — Expert Question Pool Generator"""
from __future__ import annotations
import json, re, uuid, random
from dataclasses import dataclass, asdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
GAME_ROOT = Path(__file__).resolve().parents[1]
NOTEBOOKS = [ROOT / "leet A1.ipynb", ROOT / "leetA2.ipynb"]
OUTPUT_PATH = GAME_ROOT / "data" / "generated" / "content.json"
PUBLIC_OUTPUT_PATH = GAME_ROOT / "public" / "generated" / "content.json"

def slugify(v):
    return re.sub(r"[^a-z0-9]+", "-", v.lower()).strip("-") or "item"

def clean(v):
    v = re.sub(r"<[^>]+>", " ", v)
    v = re.sub(r"\[(.*?)\]\(.*?\)", r"\1", v)
    v = re.sub(r"[`*_#]+", "", v)
    return re.sub(r"\s+", " ", v).strip()

def extract_links(text):
    return re.findall(r"https?://[^\s\)\"']+", text)

def load_cells(nb_path):
    data = json.loads(nb_path.read_text())
    return [{"idx": i, "kind": c["cell_type"], "src": "".join(c["source"])}
            for i, c in enumerate(data["cells"])]

def detect_topic(text):
    m = re.match(r"^##\s+(.+)", text.strip())
    return clean(m.group(1)) if m else None

def detect_subtopic(text):
    m = re.match(r"^###\s+(.+)", text.strip())
    return clean(m.group(1)) if m else None

def detect_problem(text):
    links = extract_links(text)
    flat = clean(text)
    m = re.search(r"(\d+)\.\s*([A-Z][A-Za-z0-9'&/ ,\-:()+]{2,80})", flat)
    if m:
        return int(m.group(1)), m.group(2).strip().rstrip("-"), links
    m2 = re.search(r"\[(\d+)\.\s*([^\]]+)\]", text)
    if m2:
        return int(m2.group(1)), m2.group(2).strip(), links
    return None, None, links

def first_sentence(text, fallback):
    text = clean(text)
    if not text: return fallback
    return re.split(r"(?<=[.!?])\s+", text)[0][:280]

def extract_insights(text):
    kws = ["key", "idea", "approach", "intuition", "pattern", "note:", "same as",
           "difference", "must", "only diff", "careful", "edge case", "optimal", "trap", "trick"]
    res = []
    for line in text.splitlines():
        cl = clean(line)
        if 15 <= len(cl) <= 200 and any(kw in cl.lower() for kw in kws):
            res.append(cl)
    return res[:5]

def extract_cues(text, topic, subtopic):
    hay = text.lower()
    cues = []
    if "shortest path" in hay and "unweighted" in hay: cues.append("unweighted shortest path → BFS")
    if "order matters" in hay or "permutation" in hay: cues.append("order matters → permutations → target outer loop")
    if "monotonic" in hay or "next greater" in hay: cues.append("nearest greater/smaller → monotonic stack")
    if "prefix" in hay and "sum" in hay: cues.append("subarray sum query → prefix sum")
    if "sliding window" in hay or "at most k" in hay: cues.append("contiguous subarray with constraint → sliding window")
    if "binary search" in hay or "sorted" in hay: cues.append("sorted/rotated array or answer range → binary search")
    if "topo" in hay or "prerequisite" in hay: cues.append("dependency ordering → topological sort")
    if "knapsack" in hay or "0/1" in hay: cues.append("item selection with capacity → knapsack DP")
    if not cues: cues.append(f"{topic} pattern")
    return cues[:4]

def parse_notebooks(paths):
    topics_map = {}
    problems = []

    for nb_path in paths:
        nb_name = nb_path.name
        cells = load_cells(nb_path)
        cur_topic = "General"; cur_topic_id = "general"
        cur_subtopic = "General"; cur_subtopic_id = "general"
        difficulty = "medium"
        prob_title = None; prob_number = None; prob_links = []
        prob_md = []; prob_code = []; prob_cells_idx = []

        def flush():
            nonlocal prob_title, prob_number, prob_links, prob_md, prob_code, prob_cells_idx
            if not prob_title: return
            all_md = "\n".join(prob_md); all_code = "\n".join(prob_code)
            summary = first_sentence(all_md, prob_title)
            insights = extract_insights(all_md + "\n" + all_code)
            cues = extract_cues(all_md, cur_topic, cur_subtopic)
            pid = f"lc-{prob_number}-{slugify(prob_title)}" if prob_number else f"lc-{slugify(prob_title)}"
            if not any(p["id"] == pid for p in problems):
                problems.append({"id": pid, "title": prob_title, "number": prob_number,
                    "topic": cur_topic, "subtopic": cur_subtopic,
                    "topicId": cur_topic_id, "subtopicId": cur_subtopic_id,
                    "difficulty": difficulty, "notebook": nb_name,
                    "source_cells": list(prob_cells_idx),
                    "summary": summary, "notes": all_md[:1200],
                    "code": all_code[:3000], "links": list(set(prob_links)),
                    "insights": insights[:5], "recognition_cues": cues[:4]})
            prob_title = None; prob_number = None; prob_links = []
            prob_md = []; prob_code = []; prob_cells_idx = []

        for cell in cells:
            text = cell["src"]; kind = cell["kind"]; idx = cell["idx"]
            t = detect_topic(text)
            if t and kind == "markdown":
                flush(); cur_topic = t; cur_topic_id = slugify(t)
                cur_subtopic = t; cur_subtopic_id = slugify(t)
                if cur_topic_id not in topics_map:
                    topics_map[cur_topic_id] = {"id": cur_topic_id, "title": cur_topic, "subtopics": set()}
                continue
            st = detect_subtopic(text)
            if st and kind == "markdown":
                flush(); cur_subtopic = st; cur_subtopic_id = slugify(st)
                if cur_topic_id in topics_map: topics_map[cur_topic_id]["subtopics"].add(cur_subtopic)
                continue
            if kind == "markdown" and text.strip().startswith("####"):
                num, title, links = detect_problem(text)
                if title and len(title) > 3:
                    flush(); prob_title = title; prob_number = num; prob_links = links
                    prob_cells_idx = [idx]; prob_md = [text]
                    difficulty = "hard" if "hard" in text.lower() else "easy" if "easy" in text.lower() else "medium"
                    continue
            if prob_title:
                prob_cells_idx.append(idx)
                if kind == "markdown": prob_md.append(text); prob_links.extend(extract_links(text))
                else: prob_code.append(text)
            elif kind == "code":
                m = re.match(r"#\s*(\d+)\.\s*(.+)", text.strip())
                if m:
                    flush(); prob_number = int(m.group(1))
                    prob_title = m.group(2).strip().split("\n")[0][:80]
                    prob_cells_idx = [idx]; prob_code = [text]
        flush()

    topics = [{"id": t["id"], "title": t["title"], "subtopics": sorted(t["subtopics"])}
              for t in topics_map.values()]
    topics.sort(key=lambda x: x["title"])
    return topics, problems


