WRONG_POOL = {
    "binary-search": ["Linear scan left to right","Sort first then scan","Use hashmap O(1) lookup","BFS level traversal"],
    "graphs": ["Greedy by edge weight","Prefix sum of matrix","Binary search on node index","Sort nodes by degree"],
    "dynamic-programming": ["Greedy local max","Sort then two pointers","Fixed-size sliding window","Binary search on answer"],
    "sliding-window": ["Sort then binary search","Nested O(n²) check","Prefix sum + hashmap","DFS on array"],
    "stack-monotonic-stack": ["Binary search for boundary","Prefix max/min arrays","Sort then greedy","Two pointers from ends"],
    "backtracking": ["DP with memoization","BFS layer enumeration","Greedy at each step","Union Find connectivity"],
    "heap-priority-queue": ["Sort all then index","Binary search sorted list","DFS for extremes","Prefix sum for ranges"],
    "trees": ["Two-pointer on array","Binary search on values","Sliding window on path","Union Find connectivity"],
    "prefix-sum": ["Sort and scan","Binary search on values","Sliding window","DFS traversal"],
    "default": ["Nested O(n²) loop","Sort and greedy select","Binary search on answer","Hash every element"],
}

def get_wrong(tid, correct):
    pool = WRONG_POOL.get(tid, WRONG_POOL["default"])
    return [c for c in pool if c.lower().strip() != correct.lower().strip()][:3]

def auto_questions(problems):
    random.seed(42); qs = []; seen = set()
    for p in problems:
        if not p["title"] or len(p["title"]) < 3: continue
        tid = p["topicId"]; title = p["title"]
        summary = p["summary"] or title
        if p["recognition_cues"]:
            cue = p["recognition_cues"][0]
            wrong = get_wrong(tid, cue)
            if len(wrong) >= 3:
                choices = [cue] + wrong; random.shuffle(choices)
                qid = f"q-recog-{slugify(title)}-{uuid.uuid4().hex[:5]}"
                if qid not in seen:
                    seen.add(qid)
                    qs.append({"id":qid,"problemId":p["id"],"topic":p["topic"],"subtopic":p["subtopic"],"topicId":tid,"subtopicId":p["subtopicId"],"difficulty":p["difficulty"],"title":f"{title} — Pattern","questionType":"multiple_choice","prompt":f"{title}: {summary[:200]} What is the primary recognition cue?","answer":cue,"acceptedAnswers":[cue],"choices":choices,"tags":[tid,"recognition"],"timeLimitSec":15,"masteryWeight":1.0,"fullCode":p["code"][:800] if p["code"] else "","fullExplanation":f"Recognition for {title}: {cue}. Topic: {p['topic']}.","links":p["links"][:1],"revealFullCodeAfterAnswer":True,"revealFullExplanationAfterAnswer":True})
        for ins in p["insights"][:2]:
            if len(ins) < 20 or len(ins) > 220: continue
            qid = f"q-fc-{slugify(title)}-{uuid.uuid4().hex[:5]}"
            if qid not in seen:
                seen.add(qid)
                qs.append({"id":qid,"problemId":p["id"],"topic":p["topic"],"subtopic":p["subtopic"],"topicId":tid,"subtopicId":p["subtopicId"],"difficulty":p["difficulty"],"title":f"{title} — Insight","questionType":"flashcard","prompt":f"Key insight for {title}:","answer":ins,"acceptedAnswers":[ins],"choices":[],"tags":[tid,"flashcard"],"timeLimitSec":10,"masteryWeight":0.8,"fullCode":p["code"][:600] if p["code"] else "","fullExplanation":ins,"links":p["links"][:1],"revealFullCodeAfterAnswer":True,"revealFullExplanationAfterAnswer":True})
    return qs

def build_bundle():
    print("Parsing notebooks...")
    topics, problems = parse_notebooks(NOTEBOOKS)
    print(f"  → {len(topics)} topics, {len(problems)} problems")
    auto_qs = auto_questions(problems)
    print(f"  → {len(auto_qs)} auto-generated questions")
    all_qs = HANDCRAFTED + auto_qs
    seen = set(); unique = []
    for q in all_qs:
        if q["id"] not in seen:
            seen.add(q["id"])
            q.setdefault("choices",[])
            q.setdefault("acceptedAnswers",[q.get("answer","")])
            q.setdefault("links",[])
            q.setdefault("tags",[])
            q.setdefault("timeLimitSec",20)
            q.setdefault("masteryWeight",1.0)
            q.setdefault("fullCode","")
            q.setdefault("fullExplanation","")
            q.setdefault("revealFullCodeAfterAnswer",True)
            q.setdefault("revealFullExplanationAfterAnswer",True)
            if not q.get("topicId") and q.get("topic"): q["topicId"]=slugify(q["topic"])
            if not q.get("subtopicId") and q.get("subtopic"): q["subtopicId"]=slugify(q["subtopic"])
            unique.append(q)
    topic_titles = {t["title"] for t in topics}
    for q in HANDCRAFTED:
        if q["topic"] not in topic_titles:
            topics.append({"id":q["topicId"],"title":q["topic"],"subtopics":[q["subtopic"]]})
            topic_titles.add(q["topic"])
        else:
            for t in topics:
                if t["title"]==q["topic"] and q["subtopic"] not in t["subtopics"]:
                    t["subtopics"].append(q["subtopic"])
    topics.sort(key=lambda x:x["title"])
    return {"meta":{"sourceNotebooks":[p.name for p in NOTEBOOKS],"topicCount":len(topics),"problemCount":len(problems),"questionCount":len(unique)},"topics":topics,"problems":problems,"questions":unique}

def main():
    bundle = build_bundle()
    for path in [OUTPUT_PATH, PUBLIC_OUTPUT_PATH]:
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text(json.dumps(bundle, indent=2, ensure_ascii=False))
        print(f"Written → {path}")
    m = bundle["meta"]; hc = len(HANDCRAFTED)
    print(f"\n✓ {m['topicCount']} topics · {m['problemCount']} problems · {m['questionCount']} questions")
    print(f"  {hc} expert handcrafted + {m['questionCount']-hc} auto-generated")

if __name__ == "__main__":
    main()
